SQL_RULES = [
    ("SQL001", "SELECT *", "Medium", "The parsed SELECT projection contains a bare Star node; aggregate COUNT(*) is not what this rule is targeting.", "Selecting every column can transfer unnecessary data and make code more sensitive to schema changes.", "Name the columns the application needs and validate that the result shape remains correct."),
    ("SQL002", "UPDATE without WHERE", "High", "The statement contains an UPDATE node and no WHERE node in the parsed tree.", "Without a restrictive condition, an update can modify every row in the target table.", "Add and test the intended predicate; use transaction/rollback safeguards for important writes."),
    ("SQL003", "DELETE without WHERE", "High", "The statement contains a DELETE node and no WHERE node in the parsed tree.", "Without a condition, all rows in the target table can be deleted.", "Add and verify a restrictive WHERE clause, preview matching rows, and use appropriate transaction safeguards."),
    ("SQL004", "Non-SARGable WHERE function", "Medium", "The implementation searches WHERE text for a set of functions including YEAR, MONTH, DAY, UPPER, LOWER, DATE, CAST, TRUNC, TO_CHAR, TO_DATE, TO_NUMBER and NVL.", "Applying a function to a column may prevent a normal index from serving the predicate efficiently.", "When semantically valid, rewrite the predicate to compare a bare column to a transformed value; otherwise evaluate an expression index."),
    ("SQL005", "SELECT without WHERE", "Low", "The rule finds a SELECT without any WHERE, but suppresses the finding for aggregate functions COUNT/SUM/AVG/MIN/MAX and GROUP BY.", "The query may read a broad set of rows; intentional reporting scans are possible.", "Add a selective condition when the application does not need all rows; judge intentional aggregates/reporting separately."),
    ("SQL006", "Leading wildcard LIKE", "Medium", "The LIKE pattern is a string literal whose value starts with `%` or `_`.", "A leading wildcard prevents a normal B-tree index from efficiently seeking to the beginning of a key range.", "Prefer prefix matching such as `name LIKE 'abc%'` when valid, or choose full-text/search functionality."),
    ("SQL007", "NOT IN with subquery", "High", "A NOT node wraps an IN node that contains a query/subquery.", "If the subquery returns NULL, three-valued logic can make NOT IN return unexpected results.", "Consider NOT EXISTS or an equivalent anti-join and check NULL semantics and the execution plan."),
    ("SQL008", "Large OFFSET", "Medium", "The top SELECT has a literal integer OFFSET of at least 1000.", "Large offsets may require processing and discarding many rows before returning a page.", "Consider keyset/seek pagination with a stable, indexed sort key."),
    ("SQL009", "Limited result without ORDER BY", "Low", "The top SELECT has a limit node and no order node; a literal LIMIT 1 is deliberately suppressed by the source rule.", "Without a defined order, the limited subset is not deterministic and can change across plans or runs.", "Add a stable ORDER BY that reflects the intended page order, ideally with a unique tie-breaker."),
    ("SQL010", "JOIN without condition / comma-join syntax", "Varies: Low/Medium/High", "An explicit CROSS JOIN is reported at Medium severity; a JOIN lacking ON/USING and multiple FROM sources without a connecting predicate are High; comma-join syntax whose WHERE has a cross-table column equality is Low.", "Missing relationships can create Cartesian row multiplication; legacy comma-join syntax can also be harder to review.", "Add ON/USING or a correct relationship predicate; prefer explicit JOIN ... ON syntax. Keep CROSS JOIN only when the Cartesian result is intentional."),
    ("SQL011", "INSERT without column list", "Medium", "An INSERT whose target is a Table rather than an explicit Schema column target is flagged.", "Values then depend on positional table order, making schema changes risky.", "Use `INSERT INTO table (col1, col2) VALUES (...)` and provide matching values."),
    ("SQL012", "OR across different columns", "Medium", "The WHERE AST contains an OR whose left/right branches refer to different sets of column names.", "The different branches may need different access paths and can be harder to optimize.", "Review selectivity; consider equivalent UNION ALL branches only if duplicate/result semantics are preserved, then compare plans."),
    ("SQL013", "Random ordering", "High", "ORDER BY expressions are checked for dialect-specific random functions, including RAND, RANDOM, DBMS_RANDOM and NEWID; Oracle includes extra DBMS_RANDOM AST/text checks.", "Random values commonly need to be evaluated for many rows and then sorted.", "Use a sampling strategy suitable for the database and requirement; validate distribution and result semantics."),
    ("SQL014", "Scalar subquery in SELECT list", "Medium", "A top-level SELECT projection expression contains a Subquery node.", "A scalar subquery may add repeated work per outer row, especially if correlated.", "Consider a JOIN, pre-aggregated derived table or window expression when equivalent; verify duplicate and NULL behavior."),
    ("SQL015", "Equality comparison to NULL", "High", "An AST equality or inequality node has a NULL on either side (`= NULL` or `<> NULL`).", "NULL comparisons evaluate to UNKNOWN rather than TRUE/FALSE in the expected way.", "Use `IS NULL` or `IS NOT NULL`."),
]

PERFORMANCE_RULES = [
    ("P001", "Full table scan", "High", "A plan table-scan operation is detected by the normalized query context.", "A scan reads a table's blocks rather than finding rows through an index; this can be expensive on a large input, but optimal for small or low-selectivity reads.", "Check table size, predicate selectivity, statistics and required output before choosing an alternate access path."),
    ("P002", "Filtered scan without supporting index", "High", "For a bare filter predicate, the target table is scanned and the filtered column has no leading supporting index.", "A selective filter may benefit from index access, depending on table size and selectivity.", "Evaluate a suitable index and validate read improvement against write/storage cost."),
    ("P003", "Explicit sort operation", "Medium", "The normalized plan contains a sort operation.", "Sorting costs CPU and memory and can spill to temporary storage for large inputs.", "Check whether a suitable index can supply the requested ORDER BY/GROUP BY order; verify the plan."),
    ("P004", "Large unrestricted scan", "High", "The statement has no WHERE and a table scan has estimated rows or known table row count at least the configured LARGE_ROWS threshold.", "An unrestricted read from a large table can move many rows and consume resources.", "Restrict the result if the application does not require the entire table; do not add a filter that changes intended output."),
    ("P005", "Non-SARGable filter", "Medium", "A predicate in the query context is marked wrapped (function/arithmetic around a column).", "The normal index key may not be usable as a seek for the transformed expression.", "Rewrite the predicate to leave the column bare where valid, or use an expression index if supported."),
    ("P006", "Join column without supporting index", "Medium", "Join pairs and join plan exist; a scanned join table has no detected index on its join column.", "Repeated lookup or join processing may be expensive without a useful access path.", "Consider an index only after checking selectivity, join direction and write overhead."),
    ("P007", "Nested loop with table scan", "Medium", "The plan has a join plus table scans and includes a NESTED_LOOPS or NESTED_LOOP_JOIN operation.", "The inner/scanned side may be revisited many times, magnifying scan cost.", "Review row estimates and possible indexed access; nested loops are not inherently bad when the outer side is small."),
    ("P008", "Implicit conversion on string column", "Medium", "A bare comparison predicate uses a numeric literal against a column whose metadata type is in the code's STRING_TYPES set.", "The database may convert a value or column and make comparisons/index usage less predictable.", "Use a type-compatible literal or parameter unless conversion is intentional; re-check application semantics."),
    ("P009", "Potentially redundant index", "Low", "A non-primary, non-unique index's columns are a left-prefix of another index's column list.", "The longer index may support the shorter index's access pattern, but constraints and workload can justify both.", "Validate constraints, measured usage, storage and write cost before dropping the shorter index."),
    ("P010", "Composite index leading column missed", "Medium", "The query filters a non-leading column of a composite index but not its first column.", "A normal B-tree seek generally starts from the leading key, so suffix-only filtering can be less effective.", "Add the leading predicate only if logically correct, or design an index whose leading columns match workload."),
    ("P011", "Covering-index opportunity", "Low", "The code excludes SELECT-star, respects a small-table threshold, and looks for a small selected/filter column set not already covered by an index.", "A covering index may avoid table lookups for a query that needs few columns, but increases index size/write work.", "Test a narrow candidate index against read benefits, storage and write overhead."),
    ("P012", "GROUP BY lacks leading index", "Medium", "The query has GROUP BY columns without an index leading on a grouped column and the plan shows a sort/grouping operation.", "The engine may need an additional sort or grouping step.", "Consider a matching index when the measured workload justifies its cost."),
    ("P013", "Heavy column without LIMIT", "Medium", "A selected column's metadata type is in the code's HEAVY_TYPES set and the query has no LIMIT/FETCH limit.", "Large text/binary or similar values can increase I/O, memory and result-transfer cost.", "Fetch heavy columns only when needed, paginate metadata, or retrieve large payloads separately."),
    ("P014", "UPDATE changes indexed column", "Medium", "An UPDATE assignment changes a column that the table's known index metadata says is indexed.", "The database must maintain index entries when indexed values change, increasing write work.", "Keep indexes that serve workload; avoid unnecessary indexes on frequently changed columns."),
    ("P015", "Join metadata type/collation mismatch", "High", "Join-column metadata differs in data type or (when both present) collation.", "Conversions or incompatible comparison semantics may hinder index matching and can cause correctness surprises.", "Align definitions where appropriate and inspect the native execution plan."),
    ("P016", "Index exists but is not used", "Medium", "A filtered column has a leading index and the normalized plan still scans that table.", "The optimizer may reject the index due to selectivity, statistics, conversion, or cost.", "Inspect statistics, selectivity and metadata before adding a second index or forcing a plan."),
    ("P017", "Join row explosion", "High", "For plans with joins and at least two child row estimates, join output estimate meets the code's LARGE_ROWS / ROW_EXPLOSION_FACTOR threshold relative to largest child.", "A very large join result relative to its inputs can indicate many-to-many multiplication or missing predicates.", "Verify join keys, uniqueness/cardinality and intended relationship; reduce rows only when semantics allow."),
    ("P018", "Large sort without limit", "High", "No query limit is present and a sort operation estimates rows at least LARGE_ROWS threshold.", "Sorting a large result without limiting rows can use substantial CPU/memory/temp I/O.", "Limit only when application semantics allow, or test an index-backed order."),
    ("P019", "Temporary/materialized intermediate", "Medium", "The normalized plan reports a temporary operation/materialization.", "An intermediate result may require extra memory, disk I/O and CPU.", "Inspect GROUP BY, DISTINCT, ORDER BY, CTEs and derived tables; simplify only if result semantics are preserved."),
    ("P020", "Large fraction read through index", "Medium", "For an index scan with row estimates and known total table rows, estimated rows/table rows is at least 30%.", "Random index access may be less efficient than a scan when a large fraction of rows is needed.", "Compare plan costs and actual performance; do not force an index simply because it exists."),
    ("P021", "Low-cardinality leading index", "Medium", "The query has a WHERE equality predicate on a large table and a leading index cardinality is known and at or below the configured low-cardinality distinct-value limit.", "A low-selectivity key can identify many rows, making the index alone less useful.", "Test a more selective composite index or let the optimizer scan if that is cheaper."),
    ("P022", "Indexed wrapped predicate with table scan", "High", "A WHERE predicate is wrapped, that column has an index, and the plan contains a table scan.", "The function/expression appears associated with the indexed column not being used for the access path.", "Rewrite to a bare-column predicate when equivalent or consider a database-supported expression index."),
]

GLOSSARY = {
    "AST": "Abstract syntax tree: a structured representation of SQL statements produced by the parser.",
    "Cardinality": "The number of rows expected or observed at an operator or result.",
    "Covering index": "An index containing all columns needed for a query path, potentially avoiding table lookups.",
    "Dialect": "A database's SQL grammar and behavior variant, such as Oracle, PostgreSQL or MySQL.",
    "Execution plan": "The physical operators and access paths selected by the database optimizer.",
    "Index selectivity": "How narrowly an index/predicate identifies rows; selective predicates match a small fraction.",
    "Materialization": "Producing an intermediate result, often into temporary memory or storage, for later operators.",
    "Nested loop": "A join strategy that iterates one input and probes the other input for each row or batch.",
    "NULL": "A marker for unknown/missing information; it is not equal to a normal value, including another NULL.",
    "Optimizer": "The database component that estimates alternatives and chooses a plan.",
    "SARGable": "A predicate form that can efficiently use an index/search access path.",
    "Statistics": "Metadata such as row counts and value distributions used by the optimizer for estimates.",
    "Table scan": "Reading table rows/blocks without using an index as the primary row access path.",
    "Three-valued logic": "SQL predicate results may be TRUE, FALSE or UNKNOWN, especially with NULL.",
    "Composite index": "An index whose key contains multiple columns in a defined order.",
    "Keyset pagination": "Paging by a stable key boundary rather than skipping a large OFFSET count.",
}

